      const n = (a, b) => { let A = P.mins(a) / 60; if (A < 18) A += 24; const B = P.mins(b) / 60 + 24; return { h: B - A, acostar: a, desp: b, guardia: false, tramos: [[A, B, 0]] }; };
      P.store.suenoReal = {};
