  // 263) DINERO COMO ASISTENTE, EN CADENA: «no es para apuntar cada día lo que gasto: es para ayudarme a
  // ahorrar según lo que gano y a no gastar de más». Sin banco, Hoy estima y pide una captura. Se pone el
  // saldo a mano (cuenta de gastos y de ahorro), los bolsillos se cuadran con el banco, Hoy dice lo que
  // queda hasta la nómina (saldo − recibos que faltan − lo que toca apartar), «ya lo he apartado» lo mete
  // en los bolsillos, Ahorro dice lo ahorrado de verdad y avisa si no cuadra, Mes enseña el mes cerrado,
  // la frase del asistente sale también en Hoy de la app, y Tu sueldo vive en Ajustes. Además, el lector
  // de verdad sobre una captura dibujada, el lector de texto con tres bancos y lo gastado con dos capturas.
  {
    const r = {};
    // esta prueba es una «foto» financiera: recibos hasta la nómina, mes cerrado y gasto se miden contra la
    // fecha de hoy. Para que no caiga según el día real (p. ej. la víspera de la nómina, el recibo de mañana
    // coincide con el cobro y no cuenta), se congela «hoy» al día 15 del mes en curso durante todo el bloque
    // y se restaura al final (mismo patrón que la prueba 69).
    await page.evaluate(() => { const Orig = Date, n = new Orig(); const frozen = new Orig(n.getFullYear(), n.getMonth(), 15, 12, 0, 0).getTime();
      window.__origDate263 = Orig;
      window.Date = class extends Orig { constructor(...a) { if (!a.length) super(frozen); else super(...a); } static now() { return frozen; } }; });
    r.ini = await page.evaluate(() => { const P = window.PG, s = P.store, h = new Date(), mañana = P.addDays(h, 1);
      window.__copia263 = JSON.parse(JSON.stringify(s));
      const mk = (i) => { const d = new Date(h.getFullYear(), h.getMonth() - i, 1); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'); };
      s.dinero = s.dinero || {}; s.dinero.pagos = [];
      s.dinero.gastos = [{ id: 'g263a', nombre: 'Alquiler', importe: 650, dia: mañana.getDate(), cat: 'casa', on: true },
        { id: 'g263b', nombre: 'Gimnasio', importe: 39, dia: P.addDays(h, 4).getDate(), cat: 'salud', on: true }];
      const a = P.ahorroS();
      a.epocas = [{ id: 'e263', nombre: 'R1', desde: '2000-01', neto: 2005, finde: 0, pagaJun: 0, pagaDic: 0 }];
      a.real = [{ fecha: mk(0) + '-01', hora: '10:00', mes: mk(1), banco: null, ingresos: 2005, gastos: 1420,
        cats: { Alquiler: 650, Gimnasio: 39, Supermercado: 210, Restaurantes: 160, Ocio: 95, Otros: 266 } }];
      a.gastado = {}; a.meses = {}; a.metaPct = 30; delete a.banco; delete a.visto;
      a.huchas = [{ id: 'hu-colchon', nombre: 'Colchón', ico: '🔒', color: '#8b5cf6', pct: 50, objetivo: 0, meta: 'no se toca', saldo: 3200 },
        { id: 'hu-viajes', nombre: 'Japón', ico: '✈️', color: '#38bdf8', pct: 30, objetivo: 2400, meta: '', saldo: 1150 },
        { id: 'hu-caprichos', nombre: 'Caprichos', ico: '🎁', color: '#fbbf24', pct: 20, objetivo: 0, meta: '', saldo: 310 }];
      a.puroId = 'hu-colchon'; a.puroPct = 50;
      const A = P.asistS(); A.sil = {}; A.nunca = {};
      P.ui.tab = 'dinero'; P.ui.dinTab = 'bosque'; P.ui.dineroVista = ''; P.ui.dinHoja = ''; P.save(); P.render();
      const m = document.querySelector('#main').innerText.replace(/\s+/g, ' ');
      // tanda Dinero D3: Dinero ya no enseña «Te queda / Puedes gastar hoy» (acta del 28/10); lo que se comprueba es el cálculo y que el Bosque no pide apuntar gastos
      return { estima: P.bkQueda() === null && !/PUEDES GASTAR|TE QUEDA/.test(m), pide: !!P.d6Mes().presu, apunta: !!document.querySelector('#main [data-a="dinero-apuntar"]') }; });
    // D6: la pantalla del banco ya no existe; lo leído antes sigue guardado. Se siembra una captura de las dos cuentas de serie
    // (1.670,32 € y 4.810 €) y se comprueba que el asistente y el cálculo la siguen usando
    await page.evaluate(() => { const P = window.PG, b = P.bancoS(), s = {};
      if (!b.cuentas.length) b.cuentas = [{ id: 'cb1', nombre: 'Cuenta nómina', num: '', rol: 'gasto' }, { id: 'cb2', nombre: 'Cuenta ahorro', num: '', rol: 'ahorro' }];
      s[b.cuentas.filter((c) => c.rol === 'gasto')[0].id] = 1670.32; s[b.cuentas.filter((c) => c.rol === 'ahorro')[0].id] = 4810;
      b.capturas.unshift({ fecha: P.iso(new Date()), hora: '10:00', s }); P.save(); P.render(); });
    r.hoy = await page.evaluate(() => { const P = window.PG, Q = P.bkQueda(), m = document.querySelector('#main').innerText.replace(/\s+/g, ' ');
      return { saldo: Q.saldo, rv: Q.rv, ap: Q.ap, queda: Q.queda, dia: Q.dia, big: String(Q.queda),
        bols: P.ahorroS().huchas.map((h) => h.saldo).join(','), asis: (() => { const t = P.dinAsis(false); return t ? JSON.stringify(t).replace(/\s+/g, ' ') : ''; })(),
        recibos: (Q.rec || []).map((x) => x.g.nombre).join(','), m: m.slice(0, 200) }; });
    await page.evaluate(() => { window.PG.ui.dinTab = 'gastos'; window.PG.render(); }); await page.click('#main [data-a="d6-tab"][data-v="mes"]'); await page.waitForTimeout(150);
    r.mes = await page.evaluate(() => ({ txt: document.querySelector('#main').innerText.replace(/\s+/g, ' '), cats: document.querySelectorAll('#main .d6cat').length }));
    // la frase del asistente, también en Hoy; y sobrevive a recargar (normalize)
    r.app = await page.evaluate(() => { const P = window.PG; P.store = JSON.parse(JSON.stringify(P.store)); const b = P.bancoS();
      P.ui.tab = 'hoy'; P.ui.hoyVista = ''; P.render(); const t = document.querySelector('#main .card.asist .astj.din');
      return { cuentas: b.cuentas.map((c) => c.nombre + ':' + c.rol).join('|'), caps: b.capturas.length, s: JSON.stringify(b.capturas[0] && b.capturas[0].s), din: t ? t.innerText.replace(/\s+/g, ' ') : '' }; });
    // Tu sueldo, en Ajustes, y vuelve a Ajustes
    await page.evaluate(() => { const P = window.PG; P.ui.tab = 'ajustes'; P.ui.ajuVista = ''; P.render(); });
    await page.click('#main [data-a="din-sueldo"]'); await page.waitForTimeout(150);
    r.sueldo = await page.evaluate(() => ({ tit: (document.querySelector('#main .subtit') || {}).textContent, epoca: !!document.querySelector('#main [data-a="aho-ep"]') }));
    await page.click('#main [data-a="din-a-aju"]'); await page.waitForTimeout(120);
    r.vuelta = await page.evaluate(() => window.PG.ui.tab + ':' + /Ajustes/.test((document.querySelector('#main .subtit') || {}).textContent || ''));
    // lo gastado con dos capturas, una antes de cada nómina: lo que entró menos lo que creció lo tuyo
    r.gasto = await page.evaluate(() => { const P = window.PG, b = P.bancoS(), h = new Date();
      const mk = (i) => { const d = new Date(h.getFullYear(), h.getMonth() - i, 1); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'); };
      const ll = (i) => { const d = new Date(h.getFullYear(), h.getMonth() - i, 25, 12); while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() - 1); return d; };
      const g = b.cuentas.filter((c) => c.rol === 'gasto')[0].id, a = b.cuentas.filter((c) => c.rol === 'ahorro')[0].id;
      const cap = (d, vg, va) => { const s = {}; s[g] = vg; s[a] = va; b.capturas.push({ fecha: P.iso(d), hora: '09:00', s }); };
      cap(ll(3), 300, 4000); cap(ll(2), 350, 4500);
      b.capturas.sort((p, q) => (q.fecha + q.hora).localeCompare(p.fecha + p.hora));
      const n = P.nominaMes(new Date(h.getFullYear(), h.getMonth() - 3, 1).getFullYear(), new Date(h.getFullYear(), h.getMonth() - 3, 1).getMonth()).neto;
      return { g: P.bkGastoMes(mk(2)), espera: Math.round(n - (4850 - 4300)) }; });
    await page.evaluate(() => { const P = window.PG; if (window.__origDate263) { window.Date = window.__origDate263; delete window.__origDate263; } P.store = window.__copia263; P.save(); P.ui.dineroVista = ''; P.ui.dinTab = ''; P.ui.ajuVista = ''; P.ui.tab = 'hoy'; P.render(); });
    const Hq = r.hoy;
    check('Dinero sin banco estima lo del día con tu nómina y tus recibos, pide una captura y no pide apuntar gastos',
      r.ini.estima && r.ini.pide && !r.ini.apunta, JSON.stringify(r.ini));
    check('Hoy: te queda = saldo − recibos que faltan hasta la nómina − lo que toca apartar, y el asistente avisa del recibo de mañana',
      Hq.saldo === 1670.32 && /Alquiler/.test(Hq.recibos) && Hq.ap === 602 && Hq.queda === Math.round(Hq.saldo - Hq.rv - Hq.ap) && Hq.big.indexOf(String(Hq.queda).replace(/\B(?=(\d{3})+(?!\d))/g, '.')) === 0 &&
      /alquiler \(650 €\)/.test(Hq.asis) && /descontado/.test(Hq.asis), JSON.stringify(Hq));
    check('Mes enseña el mes cerrado con Fintonic y en qué se fue el día a día',
      /CERRADO/.test(r.mes.txt) && /Ahorraste 585 €/.test(r.mes.txt) && r.mes.cats >= 3, r.mes.txt.slice(0, 300));
    check('las cuentas y sus saldos sobreviven a recargar y la frase de dinero sale también en Hoy',
      r.app.cuentas === 'Cuenta nómina:gasto|Cuenta ahorro:ahorro' && r.app.caps === 1 && /1670\.32/.test(r.app.s) && /alquiler/.test(r.app.din), JSON.stringify(r.app));
    check('Tu sueldo está en Ajustes y vuelve a Ajustes', r.sueldo.tit === 'Tu sueldo' && r.sueldo.epoca && r.vuelta === 'ajustes:true', JSON.stringify({ s: r.sueldo, v: r.vuelta }));
    check('con una captura antes de cada nómina sale lo gastado del mes sin Fintonic ni cifra', r.gasto.g === r.gasto.espera && r.gasto.g > 0, JSON.stringify(r.gasto));
    // (D6: se quitaron la pantalla del banco, su lector de capturas y el cuadre; lo leído se queda guardado)
  }

  // 264) HÁBITOS COMO ASISTENTE, EN CADENA: tres en marcha como mucho, «día N de ~66», el mínimo que se
  // propone solo, el obstáculo al tercer día y no al crear, «¿qué se cruzó?» que cambia el hábito, la
  // pregunta de automaticidad que lo pasa a «ya te salen solos» y deja hueco, «probar 14 días» dentro
  // del hábito, las reglas de 4:20 en su sección y Tu semana sin objetivos del trimestre. Se conduce por
  // la pantalla, tarjeta a tarjeta, con días libres para que la fecha no cambie el orden
  {
    const r = {};
    await page.evaluate(() => { const P = window.PG, s = P.store, k = (i) => P.iso(P.addDays(new Date(), -i));
      window.__copia264 = JSON.parse(JSON.stringify(s));
      s.rotation.mode = 'date'; for (let i = -1; i <= 3; i++) P.setDayOverride(k(i), 'sh-l', '');
      s.habitos = { items: [
        { id: 'hl', nombre: 'Leer', icono: '📖', color: '#38bdf8', dow: [0, 1, 2, 3, 4, 5, 6], noEn: [], auto: '', ancla: { t: 'tras', v: 'cama' }, min: '2 páginas', creado: k(33), fase: 'marcha', inicio: k(33) },
        { id: 'he', nombre: 'Estirar', icono: '🧘', color: '#c084fc', dow: [0, 1, 2, 3, 4, 5, 6], noEn: [], auto: '', ancla: { t: 'tras', v: 'comer' }, min: '3 min', creado: k(11), fase: 'marcha', inicio: k(11), obst: 'olvido', plan: '' },
        { id: 'hc', nombre: 'Cama a su hora', icono: '🛌', color: '#818cf8', dow: [0, 1, 2, 3, 4, 5, 6], noEn: [], auto: 'cama', ancla: {}, min: '', creado: k(90), fase: 'solo', soloVisto: k(10) },
        { id: 'ha', nombre: 'Agua, 2 litros', icono: '💧', color: '#38bdf8', dow: [0, 1, 2, 3, 4, 5, 6], noEn: [], auto: '', ancla: {}, min: '', creado: k(5), fase: 'espera' }], registro: {} };
      for (let i = 3; i <= 33; i++) { const x = s.habitos.registro[k(i)] = { hl: 'ok' }; if (i <= 11) x.he = 'ok'; }
      s.habitos.registro[k(1)] = { hl: 'ok' }; s.habitos.registro[k(2)] = { hl: 'ok' };
      delete s.asist; const A = P.asistS(); A.corto[P.iso(new Date())] = false;
      if (s.consumo) { s.consumo.plan = s.consumo.plan || {}; delete s.consumo.plan.tb; }
      P.ui.tab = 'habitos'; P.ui.habVista = ''; P.ui.habEd = null; P.save(); P.render(); });
    const card = () => page.evaluate(() => { const t = document.querySelector('#main .card.asist .astj'); return t ? t.innerText.replace(/\s+/g, ' ') : ''; });
    r.portada = await page.evaluate(() => document.querySelector('#main').innerText.replace(/\s+/g, ' '));
    r.c1 = await card();
    // «¿qué se cruzó?» → cansancio: el mínimo pasa a ser su plan para esos días
    await page.click('#main .astj [data-a="hab-cruzo"][data-v="cansancio"]'); await page.waitForTimeout(120);
    r.he = await page.evaluate(() => { const h = window.PG.habitosS().items.filter((x) => x.id === 'he')[0]; return h.obst + '|' + h.plan; });
    r.c2 = await card();
    await page.click('#main .astj [data-a="hab-min"]'); await page.waitForTimeout(120);
    r.min = await page.evaluate(() => window.PG.habitoEstado('he', window.PG.iso(new Date())));
    // al tercer día (y no al crear): ¿qué te lo puede impedir? → la hoja con «entonces haré…»
    r.c3 = await card();
    await page.click('#main .astj [data-a="hab-obst"][data-v="guardia"]'); await page.waitForTimeout(150);
    await page.fill('#habEdPlan', 'leer en la cama de guardia'); await page.click('#hojaDia [data-a="hab-ed-ok"]'); await page.waitForTimeout(150);
    r.hl = await page.evaluate(() => { const h = window.PG.habitosS().items.filter((x) => x.id === 'hl')[0]; return h.obst + '|' + h.plan; });
    // cada 14 días: ¿te sale sin pensar? Con el tercer «sí» seguido pasa a «ya te salen solos»
    r.c4 = await card();
    await page.evaluate(() => { const h = window.PG.habitosS().items.filter((x) => x.id === 'hl')[0], k = (i) => window.PG.iso(window.PG.addDays(new Date(), -i)); h.si = [{ f: k(28), v: true }, { f: k(14), v: true }]; window.PG.render(); });
    r.c4b = await card();
    await page.click('#main .astj [data-a="hab-si"][data-v="1"]'); await page.waitForTimeout(150);
    r.solo = await page.evaluate(() => ({ fase: window.PG.habitosS().items.filter((x) => x.id === 'hl')[0].fase, marcha: window.PG.habEnMarcha().length }));
    // queda hueco: «Empezar» el que esperaba (día 1)
    await page.click('#main .hhueco [data-a="hab-fase"][data-v="marcha"]'); await page.waitForTimeout(150);
    r.agua = await page.evaluate(() => { const P = window.PG, h = P.habitosS().items.filter((x) => x.id === 'ha')[0]; return h.fase + '|' + P.habDia(h); });
    // nuevo: «Meditar 10 minutos» con su mínimo propuesto; el cuarto en marcha espera turno
    const nuevo = async (nom) => { await page.click('#main [data-a="hab-ed"][data-id=""]'); await page.waitForTimeout(120); await page.fill('#habEdNom', nom);
      await page.click('#hojaDia [data-a="hab-ed-ancla"][data-v="tras:despertar"]'); await page.waitForTimeout(80); await page.click('#hojaDia [data-a="hab-ed-ok"]'); await page.waitForTimeout(150); };
    await nuevo('Meditar 10 minutos'); await nuevo('Inglés 20 min');
    r.nuevos = await page.evaluate(() => window.PG.habitosS().items.filter((x) => /Meditar|Inglés/.test(x.nombre)).map((x) => x.nombre + ':' + x.fase + ':' + x.min + ':' + (x.ancla.v || '')));
    // probar 14 días dentro del hábito: otro «cuándo», y a los 14 días, ¿te quedas? (aquí, volver)
    await page.click('#main [data-a="hab-ed"][data-id="ha"]'); await page.waitForTimeout(120);
    await page.click('#hojaDia [data-a="hab-ed-ancla"][data-v="tras:comer"]'); await page.waitForTimeout(80);
    await page.click('#hojaDia .hmas summary'); await page.waitForTimeout(80);
    await page.click('#hojaDia [data-a="hab-probar"]'); await page.waitForTimeout(150);
    r.prueba = await page.evaluate(() => { const h = window.PG.habitosS().items.filter((x) => x.id === 'ha')[0]; return h.prueba && (h.prueba.txt + '|' + h.ancla.v); });
    await page.evaluate(() => { const P = window.PG, h = P.habitosS().items.filter((x) => x.id === 'ha')[0]; h.prueba.desde = P.iso(P.addDays(new Date(), -14));
      // el hábito ya estaba en marcha esos 14 días: su «empezó» se adelanta con la prueba (cada día cuenta con la fase que tenía)
      (h.fases || []).forEach((x) => { if (x.f === P.iso(new Date())) x.f = h.prueba.desde; }); P.store = JSON.parse(JSON.stringify(P.store)); P.render(); });
    r.c5 = await card();
    const vuelve = await page.$('#main .astj [data-a="hab-prueba"][data-v="0"]'); if (vuelve) { await vuelve.click(); await page.waitForTimeout(120); }
    r.tras = await page.evaluate(() => { const h = window.PG.habitosS().items.filter((x) => x.id === 'ha')[0]; return (h.ancla.v || 'sin') + '|' + !!h.prueba; });
    // las de 4:20, en su sección: un T-break en marcha sale allí y no en la tarjeta de hábitos
    r.cn = await page.evaluate(() => { const P = window.PG, c = P.consumoS(); c.plan = c.plan || {}; c.plan.tb = { desde: P.iso(new Date()), dias: 7 };
      P.ui.tab = 'consumo'; P.ui.cnVista = ''; P.render(); const enCn = (document.querySelector('#main .card.asist .astj.cn') || {}).innerText || '';
      const hab = (P.asistTarjeta(P.iso(new Date())) || {}).id || ''; delete c.plan.tb; return { enCn: enCn.replace(/\s+/g, ' ').slice(0, 80), hab }; });
    // Tu semana: sin objetivos del trimestre y con la puerta a los experimentos
    r.sem = await page.evaluate(() => { const P = window.PG; P.ui.tab = 'habitos'; P.ui.habVista = 'rev'; P.render(); const t = document.querySelector('#main').innerText;
      return { obj: /OBJETIVOS DEL TRIMESTRE/.test(t), exp: !!document.querySelector('#main [data-a="hab-vista"][data-v="exp"]'), tocaban: /de los días que tocaban/.test(t) }; });
    await page.evaluate(() => { const P = window.PG; P.store = window.__copia264; P.save(); P.ui.habVista = ''; P.ui.habEd = null; P.ui.cnVista = ''; P.ui.tab = 'hoy'; P.render(); });
    check('Hábitos: en marcha 2 de 3 con «día 34 de ~66» y su mínimo, los que salen solos sin marcar y los que esperan turno',
      /EN MARCHA · 2 DE 3/.test(r.portada) && /día 34 de ~66/.test(r.portada) && /día malo: 2 páginas/.test(r.portada) && /YA TE SALEN SOLOS/.test(r.portada) && /Cama a su hora/.test(r.portada) && /ESPERAN TURNO/.test(r.portada),
      r.portada.slice(0, 400));
    check('dos fallos: «¿qué se cruzó?»; «cansancio» deja el mínimo como plan; luego «ayer no hubo…» y el mínimo vale',
      /Dos días sin estirar/.test(r.c1) && r.he === 'cansancio|solo 3 min' && /Ayer no hubo estirar/.test(r.c2) && r.min === 'min', JSON.stringify({ c1: r.c1, he: r.he, c2: r.c2, min: r.min }));
    check('al tercer día pregunta qué lo puede impedir y abre la hoja para el «entonces haré…»',
      /¿Qué te lo puede impedir/.test(r.c3) && r.hl === 'guardia|leer en la cama de guardia', JSON.stringify({ c3: r.c3, hl: r.hl }));
    check('cada 14 días, «¿te sale sin pensar?»; tres «sí» seguidos lo pasan a «ya te salen solos» y el que esperaba empieza en el día 1',
      /sin pensar/.test(r.c4b) && r.solo.fase === 'solo' && r.solo.marcha === 1 && r.agua === 'marcha|1', JSON.stringify({ c4: r.c4, c4b: r.c4b, solo: r.solo, agua: r.agua }));
    check('un hábito nuevo se crea con 4 preguntas y su mínimo propuesto («10 minutos» → «2 minutos»); con 3 en marcha, el siguiente espera turno',
      r.nuevos.join() === 'Meditar 10 minutos:marcha:2 minutos:despertar,Inglés 20 min:espera:4 min:despertar', JSON.stringify(r.nuevos));
    check('«probar 14 días» va dentro del hábito: el cambio se prueba, a los 14 días pregunta con su % y «volver» lo deja como estaba',
      /después de comer/.test(r.prueba || '') && /14 días con/.test(r.c5) && /% hecho/.test(r.c5) && r.tras === 'sin|false', JSON.stringify({ prueba: r.prueba, c5: r.c5, tras: r.tras }));
    check('las señales de 4:20 salen en su sección y no en la de hábitos; Tu semana sin objetivos del trimestre y con experimentos',
      /T-break/.test(r.cn.enCn) && !/tbreak/.test(r.cn.hab) && !r.sem.obj && r.sem.exp && r.sem.tocaban, JSON.stringify({ cn: r.cn, sem: r.sem }));
  }

  // 265) QUE NADA SE PIERDA, EN CADENA (tanda 1 del informe de código): (a) unos datos que no se leen
  //      se apartan antes de que el primer pintado guarde el ejemplo encima; (b) tras editar una comida,
  //      guardar otra ventana no le pone su nombre; (c) restaurar una copia antigua no vacía tu menú;
  //      (d) un evento «todo el día» sigue sin hora al recargar; (e) la siesta de 3 h elegida a mano no
  //      vuelve a 6 h; (f) «deshacer el borrado» de Entreno no se come lo apuntado después; (g) el «‹ atrás»
  //      de la app quita también su entrada del historial del navegador.
  {
    const r = {};
    const bueno = await page.evaluate(() => { const P = window.PG; P.ui.hojaDia = null; P.closeModal && P.closeModal(); return localStorage.getItem('planGuardias.v1'); });
    // (a) datos dañados → se recarga → lo que había queda apartado tal cual
    await page.evaluate(() => { localStorage.removeItem('planGuardias.rescate'); localStorage.setItem('planGuardias.v1', '{"shifts":[1,2],"roto":'); });
    await page.reload(); await page.waitForTimeout(500);
    r.a = await page.evaluate(() => ({ rescate: localStorage.getItem('planGuardias.rescate'), ahora: (localStorage.getItem('planGuardias.v1') || '').slice(0, 20) }));
    await page.evaluate(() => { const P = window.PG; P.ui.arranque = null; P.ui.tab = 'data'; P.ui.datosVista = 'copia'; P.render(); });
    r.aUi = await page.evaluate(() => /Hay datos apartados/.test(document.getElementById('main').innerText) && !!document.querySelector('[data-a="rescate-copiar"]'));
    await page.evaluate((b) => { localStorage.setItem('planGuardias.v1', b); localStorage.removeItem('planGuardias.rescate'); }, bueno);
    await page.reload(); await page.waitForTimeout(500);
    await page.evaluate(() => { const P = window.PG; P.store.meta.montada = true; P.ui.arranque = null; P.ui.tab = 'month'; P.render(); });
    // (b) editar una comida, cancelar, y luego guardar un plato: la comida no cambia de nombre
    r.b = await page.evaluate(async () => {
      const P = window.PG, m = P.store.meals[0], d = P.store.dishes[0];
      if (!m || !d) return 'sin datos';
      const antes = m.name;
      P.editMeal(m.id); document.querySelector('[data-a="m-cancel"]').click();
      P.editDish(d.id); document.querySelector('[data-a="m-save"]').click();
      await new Promise((ok) => setTimeout(ok, 50));
      return (P.store.meals.find((x) => x.id === m.id) || {}).name === antes ? 'igual' : 'pisada: ' + (P.store.meals.find((x) => x.id === m.id) || {}).name;
    });
    // (c) una copia antigua (sin la marca de limpieza) con una comida tuya en una toma: se queda
    r.c = await page.evaluate(() => {
      const P = window.PG, o = JSON.parse(JSON.stringify(P.store));
      delete o.meta.menuVaciado;
      const mia = { id: 'm-mia-265', name: 'Mi cena', note: '', items: [] }; o.meals.push(mia);
      const sh = Object.keys(o.menu)[0]; o.menu[sh][0].mealId = 'm-mia-265';
      P.store = o;
      return P.store.menu[sh][0].mealId;
    });
    // (d) evento sin hora → recargar (normalize) → sigue «todo el día»; (e) siesta 3 h a mano → sigue
    r.de = await page.evaluate(() => {
      const P = window.PG, o = JSON.parse(JSON.stringify(P.store));
      o.eventos.push({ id: 'ev-265', titulo: 'Congreso', hora: '', modo: 'fecha', fecha: P.iso(new Date()), dow: [], on: true });
      P.store = o; P.ui.tab = 'sueno'; P.render();
      return P.store.eventos.find((e) => e.id === 'ev-265').hora;
    });
    // la siesta se elige tocando su barra en Sueño (data-a="sn-siesta-cfg"): se pulsa una igual
    await page.evaluate(() => { const b = document.createElement('button'); b.dataset.a = 'sn-siesta-cfg'; b.dataset.v = '3';
      document.getElementById('main').appendChild(b); b.click(); });
    await page.waitForTimeout(80);
    r.e = await page.evaluate(() => { const P = window.PG; P.store = JSON.parse(JSON.stringify(P.store)); return P.store.sueno.siesta; });
    // (f) borrar el registro, entrenar, deshacer: vuelve lo de antes y lo nuevo se queda
    r.f = await page.evaluate(() => {
      const P = window.PG, hoy = P.iso(new Date());
      P.addSet(hoy, { ex: 'Sentadilla 265', kg: 60, reps: 8 });
      const antes = P.gymS().registro.length;
      P.gymWipe('log');
      P.addSet(hoy, { ex: 'Press 265', kg: 40, reps: 10 });
      P.gymUndoWipe();
      const R = P.gymS().registro;
      return { antes, despues: R.length, viejo: R.some((x) => x.ex === 'Sentadilla 265'), nuevo: R.some((x) => x.ex === 'Press 265') };
    });
    // (g) tres pantallas y tres «‹ atrás» de la app: no queda nada apilado en el navegador
    await page.evaluate(() => { const P = window.PG; P.ui.tab = 'month'; P.render(); P.ui.navHist = []; P.ui._navPushes = 0; history.replaceState({ m265: 1 }, ''); window.__s265 = JSON.stringify(history.state); });
    for (const t of ['gym', 'dinero', 'habitos']) { await page.evaluate((t) => { const P = window.PG; P.ui.tab = t; P.render(); }, t); await page.waitForTimeout(40); }
    for (let i = 0; i < 3; i++) { await page.evaluate(() => { const b = document.querySelector('[data-a="nav-atras"]'); if (b) b.click(); }); await page.waitForTimeout(120); }
    r.g = await page.evaluate(() => ({ igual: JSON.stringify(history.state) === window.__s265, estado: history.state, tab: window.PG.ui.tab }));
    check('unos datos que no se leen se apartan tal cual antes de guardar el ejemplo, y Datos lo enseña',
      r.a.rescate === '{"shifts":[1,2],"roto":' && r.aUi, JSON.stringify(r.a) + ' ui=' + r.aUi);
    check('tras editar una comida, guardar otra ventana no le pone su nombre', r.b === 'igual', r.b);
    check('restaurar una copia antigua no vacía las comidas que pusiste tú', r.c === 'm-mia-265', r.c);
    check('un evento «todo el día» sigue sin hora al recargar', r.de === '', JSON.stringify(r.de));
    check('la siesta del saliente de 3 h elegida a mano no vuelve a 6 h al recargar', r.e === 180, String(r.e));
    check('«deshacer el borrado» de Entreno trae lo borrado y conserva lo apuntado después',
      r.f.viejo && r.f.nuevo && r.f.despues === r.f.antes + 1, JSON.stringify(r.f));
    check('el «‹ atrás» de la app quita su entrada del historial: el atrás del móvil no se queda pillado',
      r.g.igual && r.g.tab === 'month', JSON.stringify(r.g));
  }

  // 266) SALUD Y DINERO, EN CADENA (tanda 2 del informe de código): (a) «copos de avena y trigo» ya no
  //      sale «sin gluten»; (b) un solo lector de importes: «1.500» en una hucha son 1.500 € y «-200» no la
  //      pone a 0; (c) la captura del banco no pega letras ni cuentas a los importes; (d) «ya lo he
  //      apartado» al cobrar tiene su propio registro y su «deshacer», y no deja el cierre del mes como
  //      repartido; (e) sin Fintonic, banco ni tu cifra no hay «has ahorrado» inventado; (f) una captura de
