      const borradas = llamadas.filter((x) => /^DELETE https:\/\/worker\.ejemplo\.dev\/cal\/abcdefghijklmnopqrstuvwx\//.test(x)).length;
      return { pendiente, borradas, nuevo: c.buzon !== 'abcdefghijklmnopqrstuvwx' };
